update public.learning_paths
set
  title = 'Painting II',
  goal = 'Painting II',
  summary = 'Painting II moves students toward independent inquiry, advanced technique, larger scale, mixed media, conceptual clarity, and a coherent final body of work.',
  data = $pa2json${"slug": "painting-ii", "title": "Painting II", "description": "Painting II moves students toward independent inquiry, advanced technique, larger scale, mixed media, conceptual clarity, and a coherent final body of work.", "topics": [{"id": "05e01105-6f80-4535-9e1d-b8b4c833ce76", "type": "topic", "title": "Advanced Painting Practice and Ambitious Studio Goals", "description": "Painting II begins by moving students from assignment completion toward self-directed studio practice. The focus is on clearer intentions, stronger work habits, more ambitious problems, and the ability to sustain a project beyond a single exercise.", "children": [{"id": "70a2077d-cc71-49f6-93fb-0577a1899f02", "type": "subtopic", "title": "Advanced studio expectations", "children": [{"id": "6d856d8a-a70a-4403-a6dc-07eec31279fc", "type": "concept", "title": "Independent project pacing"}, {"id": "5ee1cd72-0a66-4ba2-a692-8915ce9069a6", "type": "concept", "title": "Higher standards for revision"}, {"id": "d198d48d-89f7-4412-bb9a-3a16488123cc", "type": "concept", "title": "Risk-taking with technical follow-through"}], "description": "Students learn what changes when painting becomes a sustained practice rather than a set of introductory studies."}, {"id": "db08318b-32af-4174-befa-8b1109f69c39", "type": "subtopic", "title": "Research-driven studio planning", "children": [{"id": "4997abf6-9cb2-461c-ae38-3df62f3ef23a", "type": "concept", "title": "Studio proposal writing"}, {"id": "a1e38b3c-a239-40ed-beee-dae7a7dc48e6", "type": "concept", "title": "Artist precedent folders"}, {"id": "71c5c4cd-fa6c-471e-a10b-ac740bcddcb6", "type": "concept", "title": "Material and visual research logs"}], "description": "Advanced painting benefits from questions, precedents, and constraints that give the work direction."}, {"id": "acae2e87-dd5b-4b56-94ab-e6cb7d81e703", "type": "subtopic", "title": "Reflective practice", "children": [{"id": "618d76ab-dbce-47cc-888a-e12b1ba2f18a", "type": "concept", "title": "Process notes"}, {"id": "5d1b59bb-3dda-4b62-8636-7ceb7b8e4343", "type": "concept", "title": "Failure analysis"}, {"id": "9947bcc2-65d8-431f-a5ea-4456345d8354", "type": "concept", "title": "End-of-project self-assessment"}], "description": "Reflection helps students identify patterns in their choices and develop a more intentional practice."}]}, {"id": "874658fe-cb44-4ccb-a735-ead647bdad5e", "type": "topic", "title": "Advanced Paint Handling, Surface, and Material Systems", "description": "This section deepens technical control of paint, support, ground, surface, and layering. Students learn to treat material decisions as expressive and conceptual choices, not merely craft preferences.", "children": [{"id": "9db27cb5-07ab-4448-9489-6ec4a28a6845", "type": "subtopic", "title": "Layering and surface complexity", "children": [{"id": "e5090524-2225-4636-a3fe-986d93d6335a", "type": "concept", "title": "Glazing and scumbling"}, {"id": "be1add4f-fdcb-4150-bb1d-5242e6064c91", "type": "concept", "title": "Scraping, sanding, and excavation"}, {"id": "51f5650e-85b5-4294-bc67-b3f73bd54bea", "type": "concept", "title": "Transparency and opacity systems"}], "description": "Layering gives paintings depth, history, and a visible record of decisions."}, {"id": "c05b5b0f-4c1b-43d5-8715-3800b3a6b21d", "type": "subtopic", "title": "Material behavior and compatibility", "children": [{"id": "a3f40fae-88a4-49db-9c0f-ce47620896d0", "type": "concept", "title": "Acrylic over oil restrictions"}, {"id": "597cc55e-6388-4f5a-8900-28a468663bc0", "type": "concept", "title": "Mediums, binders, and grounds"}, {"id": "ec9eb698-d607-46e7-91a9-1242cfd0b810", "type": "concept", "title": "Archival risks and controlled exceptions"}], "description": "Students learn how different materials behave together so experimentation remains structurally sound."}, {"id": "284574a1-bda0-4ea2-a35a-c2fd29cb4778", "type": "subtopic", "title": "Surface as content", "children": [{"id": "d6c6812d-d58d-417a-98d3-09151f34b60b", "type": "concept", "title": "Smooth vs textured grounds"}, {"id": "9d1e3e2b-db1b-459c-a03a-881b00b32ca4", "type": "concept", "title": "Impasto and relief"}, {"id": "a099bfd0-74ea-43df-817a-ee1e4625f552", "type": "concept", "title": "Stain, seep, and exposed support"}], "description": "The surface can carry meaning through texture, damage, polish, accumulation, or restraint."}]}, {"id": "35a7b382-f6ca-4089-a8a9-3fd3bfdc9e17", "type": "topic", "title": "Color, Light, and Perceptual Complexity", "description": "Painting II expects students to use color and light with greater subtlety. Color is studied as perception, structure, atmosphere, mood, and conceptual code.", "children": [{"id": "0921bd68-817e-4585-8d1e-1a5042143400", "type": "subtopic", "title": "Advanced color relationships", "children": [{"id": "3af56425-504d-477b-bb28-49b023e3b516", "type": "concept", "title": "Broken color"}, {"id": "2b20d571-e0b0-4fe2-9611-072f792aa683", "type": "concept", "title": "Simultaneous contrast"}, {"id": "127bcdef-05a9-4bf1-a97f-bb5f2164ae39", "type": "concept", "title": "Chroma control and color intervals"}], "description": "Students refine color through relational judgment instead of formulaic color-wheel answers."}, {"id": "d3e5d051-0ac3-4cdd-9af9-4c278785984d", "type": "subtopic", "title": "Light as structure and mood", "children": [{"id": "bd8fe6e5-fd0c-48fe-8c45-17dc5afb375b", "type": "concept", "title": "Artificial vs natural light"}, {"id": "dffcbf37-c945-4133-96cb-b53ba749f25a", "type": "concept", "title": "Atmospheric color"}, {"id": "61bf96e2-1a13-40af-8c57-75f0c1dd6a52", "type": "concept", "title": "Backlighting, glare, and reflected light"}], "description": "Light can organize space, establish time, and shape emotional tone."}, {"id": "a302972e-eaba-4fcf-b6d6-70dbb7bf95a1", "type": "subtopic", "title": "Palette strategy", "children": [{"id": "3cb90035-449b-41fe-b886-ef8696f780c0", "type": "concept", "title": "Restricted palettes"}, {"id": "59ad7277-0a9c-4dda-b8ad-b4fb8e73aca2", "type": "concept", "title": "Key color and color anchors"}, {"id": "0656dd59-bfd0-4bb0-a4c1-6a972794761d", "type": "concept", "title": "Palette shifts across a series"}], "description": "A coherent palette can unify a series and clarify a painter's voice."}]}, {"id": "77af2fb6-5de4-489c-bf69-d7cdb1703210", "type": "topic", "title": "Composition, Geometry, Scale, and Pictorial Architecture", "description": "Advanced composition asks students to build images with durable internal architecture. The painting should hold attention through structure, rhythm, balance, tension, and spatial intelligence.", "children": [{"id": "b3ca4bd3-113b-4005-8297-e69ae0fdcc19", "type": "subtopic", "title": "Compositional geometry", "children": [{"id": "31306aff-fe7f-4f5d-850c-ae1f50ca28e7", "type": "concept", "title": "Armatures and diagonals"}, {"id": "120f743b-590f-49a4-a131-1f26c9d3d01a", "type": "concept", "title": "Golden section and proportional systems"}, {"id": "3705888f-9eb4-45cb-83f6-b6694ed031c5", "type": "concept", "title": "Asymmetry and visual tension"}], "description": "Geometry gives paintings an underlying order even when the surface looks intuitive."}, {"id": "d2facbc5-e48d-4de5-8f87-a07adad74ca2", "type": "subtopic", "title": "Spatial compression and expansion", "children": [{"id": "16d927da-b075-4fd4-9b24-099120ee2c3b", "type": "concept", "title": "Flattened space"}, {"id": "14a87ea4-217b-49f2-9f3b-d4e69792ad66", "type": "concept", "title": "Layered depth"}, {"id": "3afcbdcf-2a97-41e7-aad9-ba7cee14734c", "type": "concept", "title": "Multiple viewpoints"}], "description": "Students learn to move between illusionistic, shallow, fractured, and symbolic spaces."}, {"id": "37a27e75-febd-476b-9665-cbdd7b8ae3d5", "type": "subtopic", "title": "Compositional revision", "children": [{"id": "1142d3ae-0589-4d5d-8653-a63f62cfa601", "type": "concept", "title": "Cropping and reformatting"}, {"id": "aaac8e52-d5e8-4b9a-8cb7-5e46e5bed9e0", "type": "concept", "title": "Value redistribution"}, {"id": "d47e1ff3-d440-4e6b-bf76-d546cb88ea83", "type": "concept", "title": "Focal point control"}], "description": "Revision teaches students to improve a painting's structure after the first idea has arrived."}]}, {"id": "4f7b18ad-6258-4afb-b109-93475e367c18", "type": "topic", "title": "Large-Scale Painting and Physical Presence", "description": "Large-scale work changes the body, pace, tool choice, viewer distance, and installation logic of painting. Students learn how scale creates presence and responsibility.", "children": [{"id": "b3f8e6f9-feb4-4440-bfd2-af732380f9d9", "type": "subtopic", "title": "Scaling up ideas", "children": [{"id": "c7e92f8e-927d-49a3-bc22-433bb4706994", "type": "concept", "title": "Small study to large work"}, {"id": "9fe86db5-48cf-431b-a8c5-d9b70e3a2575", "type": "concept", "title": "Mark size and viewing distance"}, {"id": "9c38fa51-5edc-4755-a10d-949cfc998e90", "type": "concept", "title": "Format and support engineering"}], "description": "Not every small image survives enlargement, so students learn how to redesign for scale."}, {"id": "ae845191-32f9-41ce-8805-9faee2d4bf9b", "type": "subtopic", "title": "Physical painting methods", "children": [{"id": "9d04cd14-e218-4292-b42c-6766b34395ef", "type": "concept", "title": "Standing and wall-based work"}, {"id": "b3bdffd1-9b60-4e18-a5f2-631abc3275db", "type": "concept", "title": "Large brushes, rollers, and pours"}, {"id": "e78171f9-186d-4ccb-b9dc-8e2d8a6e51c3", "type": "concept", "title": "Working wet sections and drying time"}], "description": "Large paintings require bodily movement, broader tools, and new sequencing."}, {"id": "a29b77e4-0be6-429e-afce-a7947af808ed", "type": "subtopic", "title": "Viewer encounter", "children": [{"id": "10648672-c298-40bb-95dd-a23db8077306", "type": "concept", "title": "Distance and approach"}, {"id": "90190283-359c-49fd-b56d-29ac903187b5", "type": "concept", "title": "Edge-to-edge activation"}, {"id": "cd7f1b9d-947d-4b9b-a7c9-0dab3f0085a2", "type": "concept", "title": "Installation height and sightline"}], "description": "Scale shapes whether a painting feels intimate, confrontational, immersive, or architectural."}]}, {"id": "c750e67f-9aa9-41a4-978b-1a40a40b66a8", "type": "topic", "title": "Mixed Media, Collage, and Expanded Surface", "description": "Mixed media expands what a painting can contain and how it can be constructed. Students learn to integrate materials so additions feel necessary rather than decorative.", "children": [{"id": "dd9cbfea-8ea7-4fed-a86b-c2d177fb1111", "type": "subtopic", "title": "Collage and assemblage in painting", "children": [{"id": "e9d644bb-2a80-4fea-9ab3-314c654ae8ff", "type": "concept", "title": "Paper, fabric, photo, and print fragments"}, {"id": "b51b8c4d-48e3-4450-b537-01f28c327f14", "type": "concept", "title": "Adhesives and surface preparation"}, {"id": "496cbec3-d4ef-47f0-8f2e-bc0439ac9c8e", "type": "concept", "title": "Image interruption and layering"}], "description": "Collage introduces found material, fragmentation, and new relationships between image and object."}, {"id": "d625bbd8-d8fd-4eeb-bebc-3d98ad429065", "type": "subtopic", "title": "Drawing, print, and digital transfer", "children": [{"id": "2abdb783-ec9d-4db5-a2b2-b6c7c069ed80", "type": "concept", "title": "Graphite, charcoal, ink, and pastel"}, {"id": "4cd1ca55-f167-48cd-a720-10f2fc3824ce", "type": "concept", "title": "Monotype and transfer processes"}, {"id": "dce6085a-5a20-4540-b196-dca4821c5bb7", "type": "concept", "title": "Digital sketches and printed sources"}], "description": "Cross-media methods allow students to import marks, images, and systems into painting."}, {"id": "a3e510e5-8e7a-473a-a1d2-cf9e9ff9b9f2", "type": "subtopic", "title": "Expanded painting", "children": [{"id": "2c38661c-cf68-4eca-be23-ffc47cc0d90f", "type": "concept", "title": "Shaped supports"}, {"id": "750ab64e-765f-468a-92aa-2deedbe11fe5", "type": "concept", "title": "Painted objects"}, {"id": "c37ab2dd-c22e-43a8-b5c3-51f9b23c7380", "type": "concept", "title": "Modular panels and installation components"}], "description": "Painting can move beyond the stretched canvas into objects, walls, space, and installation."}]}, {"id": "06a28f19-2759-4073-9b74-7613efd60bfd", "type": "topic", "title": "Abstraction, Figuration, and Hybrid Image Languages", "description": "Painting II treats abstraction and figuration as a continuum. Students learn to decide how much recognition, ambiguity, gesture, and representation a painting needs.", "children": [{"id": "56060de0-5666-44e0-b35f-b7011541ebad", "type": "subtopic", "title": "Advanced abstraction", "children": [{"id": "c4779f8d-f739-4436-9d58-6748ee1b5f80", "type": "concept", "title": "Nonobjective composition"}, {"id": "49866686-c84a-44f3-ab07-7c47f95e996b", "type": "concept", "title": "Pattern and field"}, {"id": "e0e70551-1ff8-4140-9f8a-1743ccc0de68", "type": "concept", "title": "Gesture, stain, and reduction"}], "description": "Abstraction can be structured by process, sensation, systems, memory, or material logic."}, {"id": "df7406db-ffd3-4b1c-91b5-26ac8a14fdc0", "type": "subtopic", "title": "Figuration beyond likeness", "children": [{"id": "1605b5ee-e6b3-469f-a9c3-1daca3e80240", "type": "concept", "title": "Distortion and simplification"}, {"id": "ad299d65-13c4-49e0-a16e-eee63d046b36", "type": "concept", "title": "Body fragments and silhouettes"}, {"id": "c7e4bbc4-75aa-4dca-80ef-64afa23b167e", "type": "concept", "title": "Symbolic or expressive figuration"}], "description": "Figuration can address body, identity, narrative, distortion, and psychological presence."}, {"id": "20bc8a2f-422b-455a-9a6d-c6b478e47e19", "type": "subtopic", "title": "Hybrid languages", "children": [{"id": "d03ab5b0-1222-413e-a553-caed5d1a774f", "type": "concept", "title": "Veiling and reveal"}, {"id": "62afa83f-b9df-41e1-ab03-cbf04b29089d", "type": "concept", "title": "Fragmented image fields"}, {"id": "a855d9cf-d917-42ba-9d33-eda2a5272e59", "type": "concept", "title": "Ambiguous figure-ground relationships"}], "description": "Hybrid painting allows recognition and abstraction to pressure each other."}]}, {"id": "b6d3bd05-dec6-4dff-a706-75d0537ddd22", "type": "topic", "title": "Painting from Imagination, Memory, and Invention", "description": "Students move beyond direct observation into invented imagery while preserving structural clarity and material conviction. Imagination becomes something built through sketches, references, memory, and revision.", "children": [{"id": "9a6f7a9f-98e5-4741-9f6f-accb0fd0068b", "type": "subtopic", "title": "Memory as source", "children": [{"id": "937f7280-c5b5-439f-91f0-4edfe1bfebf5", "type": "concept", "title": "Memory mapping"}, {"id": "e81f2d9a-22f0-4dfb-a71a-ce24c7c1a820", "type": "concept", "title": "Reconstructed interiors and places"}, {"id": "7ffeccf6-94a7-4072-9ae3-c4b32bf9a07f", "type": "concept", "title": "Distortion through recollection"}], "description": "Memory can transform observed experience into selective, emotionally charged imagery."}, {"id": "c1c73f58-900d-4cf2-ba36-5d1074d92437", "type": "subtopic", "title": "Invented imagery", "children": [{"id": "db49c234-bf1c-4e5d-a59a-f94f0b6fa02a", "type": "concept", "title": "World-building"}, {"id": "ed5ace82-9dca-40f8-8587-2513abf62347", "type": "concept", "title": "Symbolic environments"}, {"id": "83fdaf9a-af44-4dea-a7a6-4cc661b778a0", "type": "concept", "title": "Dream logic and surreal structures"}], "description": "Invented paintings need internal logic even when they reject realism."}, {"id": "a905dc29-6d1c-4e4e-807b-7affcf62a8a7", "type": "subtopic", "title": "Reference synthesis", "children": [{"id": "e7db94d1-6504-4f9a-a430-a8c7399e2be0", "type": "concept", "title": "Composite studies"}, {"id": "b5e2c33f-9163-4b4d-abb0-b02eb257f37d", "type": "concept", "title": "Reference hierarchy"}, {"id": "60de7b61-0c17-45c4-bfc4-d5f1bb88b25c", "type": "concept", "title": "Invented transitions and connective tissue"}], "description": "Advanced students combine references without letting any single source dominate."}]}, {"id": "d8ca1cd7-0540-45a9-9522-52096130c066", "type": "topic", "title": "Image Sources, Translation, Appropriation, and Screens", "description": "Contemporary painting often responds to photographs, online images, archives, film, and screens. Students learn to translate sources critically and ethically rather than simply reproduce them.", "children": [{"id": "718c14da-be1a-49a0-906c-fab0d6b5b851", "type": "subtopic", "title": "Photo-based painting", "children": [{"id": "abf601f2-1987-42df-a38f-ad4fa6d71f59", "type": "concept", "title": "Cropping and framing"}, {"id": "f54e22ab-2f6d-4012-ad65-df0037d49046", "type": "concept", "title": "Lens distortion"}, {"id": "bfbb31ad-9ba3-4aab-abe1-3aa5fb2f54b3", "type": "concept", "title": "Color shifts from screen to paint"}], "description": "Photo sources can support complex imagery, but translation must create painterly purpose."}, {"id": "4dbbd43c-538c-4c53-ab36-9170c3b2246e", "type": "subtopic", "title": "Appropriation and citation", "children": [{"id": "cde779e0-b1f1-40a4-b1c2-0c9f253161e8", "type": "concept", "title": "Fair use basics"}, {"id": "bf3ed15b-6085-4b2f-bd88-41bda1ab754c", "type": "concept", "title": "Transformative use"}, {"id": "a0635df3-6db8-436a-9bd7-c1872019632d", "type": "concept", "title": "Source logs and attribution"}], "description": "Borrowing images carries legal, ethical, and cultural responsibilities."}, {"id": "a260290d-dcb4-4b2d-b76f-db79c8812bb0", "type": "subtopic", "title": "Painting after screens", "children": [{"id": "7e985090-8831-4d93-9426-57318c91c4bb", "type": "concept", "title": "Pixelation and blur"}, {"id": "df8f1132-6265-406b-b54c-15a117af9dda", "type": "concept", "title": "Scrolling and cropping"}, {"id": "d1dcf5df-a6ec-41ee-969e-754e7b2bf8fa", "type": "concept", "title": "Digital artifacts as pictorial language"}], "description": "Screens shape contemporary vision through glow, compression, repetition, and circulation."}]}, {"id": "505b203c-852a-42ee-b4df-3e62120b52af", "type": "topic", "title": "Conceptual Painting and Research Methods", "description": "Conceptual painting asks students to define the idea or question driving the work. Research becomes a studio tool for making paintings with stronger stakes and clearer intentions.", "children": [{"id": "225e7935-288a-4239-b21c-26d4bcc1f72c", "type": "subtopic", "title": "Concept development", "children": [{"id": "7cf98d0b-acdc-4ce8-bbe5-bde2ef4a7ddc", "type": "concept", "title": "Project questions"}, {"id": "494352cd-7359-4c41-a018-f53874f18dbc", "type": "concept", "title": "Visual problem statements"}, {"id": "9222f4cc-1e45-4c42-891b-27057af6a5fc", "type": "concept", "title": "Material-concept alignment"}], "description": "Students learn to articulate what the painting investigates without overexplaining the image."}, {"id": "a73f069b-5b10-4e5c-bd1c-8bdc8fab6f7c", "type": "subtopic", "title": "Research methods for painters", "children": [{"id": "cd407b1c-a9f6-42aa-be5e-933f5c31ef29", "type": "concept", "title": "Archives and collections"}, {"id": "046272f0-bf41-482b-8cb3-385416d8adeb", "type": "concept", "title": "Field observation"}, {"id": "927e2457-c489-4a4e-a278-c00ae6110677", "type": "concept", "title": "Artist interviews and criticism"}], "description": "Research can be visual, textual, historical, social, or material."}, {"id": "a9f254b8-f644-45d4-a802-3833c05dc8be", "type": "subtopic", "title": "Form and concept alignment", "children": [{"id": "ff751639-d91f-4b1d-afa5-01ce8e76fc18", "type": "concept", "title": "Constraint-based making"}, {"id": "0fb9fb5e-abb0-4ccb-96dd-0ca806ca1e98", "type": "concept", "title": "Symbolic material choices"}, {"id": "0706cdc9-8a55-4093-9043-81cde9e432a5", "type": "concept", "title": "Image systems and repetition"}], "description": "The best conceptual choices are visible in the painting's materials, scale, process, and presentation."}]}, {"id": "efb5cffe-e9e8-4fc6-9b71-4c903784452d", "type": "topic", "title": "Historical Influences, Artist Lineage, and Contemporary Context", "description": "Students build a conscious relationship to painting history and contemporary practice. The goal is to locate influences, not imitate them passively.", "children": [{"id": "308e6a67-c066-408f-935e-018f72cb04e9", "type": "subtopic", "title": "Historical reference as method", "children": [{"id": "f228865c-002c-4cd4-96ad-ebb7d52b6b4d", "type": "concept", "title": "Modernism and abstraction"}, {"id": "54eed714-34a1-49a7-a2c5-10e2cf505940", "type": "concept", "title": "Expressionism and realism"}, {"id": "75364731-dcda-4dd9-99dd-2b7daa91f81d", "type": "concept", "title": "Still life, landscape, portrait traditions"}], "description": "Historical study gives painters tools for composition, subject, surface, and argument."}, {"id": "bffaf9e2-9d6b-4851-97ec-01b8de42e23d", "type": "subtopic", "title": "Contemporary painting debates", "children": [{"id": "e18671d4-74b4-445a-b327-a36cd56cbff2", "type": "concept", "title": "Painting after photography"}, {"id": "1714d659-500b-4d49-912e-bd967236c6a4", "type": "concept", "title": "Expanded painting"}, {"id": "3628a8f2-709f-4fbc-8b62-163ed23722ab", "type": "concept", "title": "Global and decolonial perspectives"}], "description": "Students examine current questions about medium, image culture, identity, and global art contexts."}, {"id": "7ae1a66f-b7bf-4ce7-92bb-8bee63af2b06", "type": "subtopic", "title": "Artist lineage mapping", "children": [{"id": "6257d370-f55b-42c2-9231-64c789254582", "type": "concept", "title": "Influence charts"}, {"id": "33ce2e6e-7d22-4cbf-a259-7903736dc8a0", "type": "concept", "title": "Formal comparison"}, {"id": "b51b210d-3475-4eec-824f-1c5e2529e873", "type": "concept", "title": "Critical distance from influences"}], "description": "Lineage maps help students identify where their work sits in relation to others."}]}, {"id": "835fcc05-766c-4780-99f0-8e56e5d4c296", "type": "topic", "title": "Series Development and Body of Work", "description": "Painting II should culminate in connected work, not isolated assignments. Series development teaches continuity, variation, pacing, and depth.", "children": [{"id": "f7bf1f18-889b-4f60-b1ee-6689f1e755c6", "type": "subtopic", "title": "Series logic", "children": [{"id": "fea43eb9-2715-4840-aab1-8ccaad6cb51d", "type": "concept", "title": "Theme and motif"}, {"id": "971a8d2c-ce19-4281-9c90-066056759532", "type": "concept", "title": "Rule-based variation"}, {"id": "82b04d20-5951-4afe-bc10-2a112c3c7ada", "type": "concept", "title": "Formal continuity"}], "description": "A series gives students a framework for sustained inquiry."}, {"id": "5765b29a-8933-4475-95dc-62deebb7f298", "type": "subtopic", "title": "Editing and sequencing", "children": [{"id": "43c33e89-020f-4de5-9bb9-e293988eca10", "type": "concept", "title": "Selecting strongest works"}, {"id": "24c73416-dacd-4412-8fb1-cac7ab2df42a", "type": "concept", "title": "Pacing contrast"}, {"id": "8b214814-8fbd-488a-8c42-ea1615a9f8c4", "type": "concept", "title": "Sequence as meaning"}], "description": "Editing teaches students what belongs, what repeats too easily, and what strengthens the whole."}, {"id": "c701c62d-83b8-4231-b275-20ae276c561c", "type": "subtopic", "title": "Development over time", "children": [{"id": "68da55af-50f7-427e-b41f-138884feecd8", "type": "concept", "title": "Versioning"}, {"id": "2a456beb-ec1a-497a-b1dd-f96c6311ff31", "type": "concept", "title": "Breakthrough and dead-end analysis"}, {"id": "49575fde-b1df-48e1-951e-7c3a8425f59c", "type": "concept", "title": "Progressive complexity"}], "description": "A body of work should show evolution rather than repetition."}]}, {"id": "4ada26e2-768b-4665-87ad-b20e8ee5e3a6", "type": "topic", "title": "Personal Voice, Style, and Critical Position", "description": "Personal voice is treated as an emerging pattern of commitments, questions, materials, and visual decisions. Style is not decoration; it is the visible structure of a painter's thinking.", "children": [{"id": "38deb6e9-1278-4b61-abee-01f1394b73c5", "type": "subtopic", "title": "Identifying recurring concerns", "children": [{"id": "580e418a-1a2b-4ba2-ad91-a81c8079a7fe", "type": "concept", "title": "Motifs and subjects"}, {"id": "2bb08649-bba2-4038-b86b-8d8fd5217f72", "type": "concept", "title": "Material preferences"}, {"id": "1af800d8-47b9-4e59-adbc-492bd1315eac", "type": "concept", "title": "Emotional and conceptual patterns"}], "description": "Students learn to recognize what they return to and why it matters."}, {"id": "eed62531-903e-4dec-bfd1-65e42e677a1d", "type": "subtopic", "title": "Style as decision system", "children": [{"id": "4e7b13c4-4423-4a61-be43-649091fe6104", "type": "concept", "title": "Color habits"}, {"id": "125b9466-8307-4ec9-8116-fcde12939381", "type": "concept", "title": "Mark vocabulary"}, {"id": "a05fcd85-c464-4bbb-bd0e-3712b0a0c42b", "type": "concept", "title": "Spatial and compositional tendencies"}], "description": "Style becomes stronger when students can explain its recurring choices."}, {"id": "3ca7d589-2f7d-4874-a0b4-dbe9478a8dd4", "type": "subtopic", "title": "Critical position", "children": [{"id": "1a1d1f09-456b-4e12-8ca8-e1be491f9323", "type": "concept", "title": "Audience and context"}, {"id": "bff31d93-bd99-4c5e-b338-164ddfb0c3c1", "type": "concept", "title": "Social and personal stakes"}, {"id": "2744e9d3-8c2d-4695-8eca-b5bf839ec45a", "type": "concept", "title": "Statement of artistic priorities"}], "description": "Students begin to define what their work says, resists, values, or questions."}]}, {"id": "26927f61-5aab-4c0c-ba84-8347a3e5870a", "type": "topic", "title": "Studio Critique, Peer Dialogue, and Revision", "description": "Group critique becomes more demanding in Painting II. Students practice precise language, interpretive generosity, evidence-based claims, and revision plans.", "children": [{"id": "92c48739-3b1b-429d-8f8a-fdbc388574bf", "type": "subtopic", "title": "Advanced critique formats", "children": [{"id": "0c96dcc6-147f-42ff-bc98-90bae2d670c1", "type": "concept", "title": "Formal critique"}, {"id": "3f9e3ac7-3d30-4892-b266-4419200e6ff5", "type": "concept", "title": "Concept critique"}, {"id": "1d3cb47a-6862-4052-a53f-561e788a384e", "type": "concept", "title": "Installation and series critique"}], "description": "Different critique structures reveal different kinds of information about a painting."}, {"id": "30eede2b-dca5-4d9d-99e3-2f190d1c09f2", "type": "subtopic", "title": "Giving and receiving feedback", "children": [{"id": "38ff0b92-5f71-4428-8ac9-8427ecb9450a", "type": "concept", "title": "Specific evidence"}, {"id": "a8ac271b-2695-4348-8005-927d089cbf11", "type": "concept", "title": "Questions before advice"}, {"id": "8a91535e-3f07-411d-8271-65cf6886f9ec", "type": "concept", "title": "Revision priorities"}], "description": "Students learn to turn critique into useful action without surrendering authorship."}, {"id": "eb838a1f-33b0-434f-8ce3-7cdf2a676eda", "type": "subtopic", "title": "Revision as studio method", "children": [{"id": "acc23e6b-e793-4475-98fc-caf30873f388", "type": "concept", "title": "Overpainting"}, {"id": "f79bb9c4-c45c-4785-82c2-80b9a4b324a8", "type": "concept", "title": "Structural change"}, {"id": "d63f7e1e-e3ad-47b4-aa1a-bfacb55ebabd", "type": "concept", "title": "Documenting before/after decisions"}], "description": "Revision is framed as a central creative act rather than a correction of failure."}]}, {"id": "3c561fb2-9b96-42e7-b4f5-a77832c83fe7", "type": "topic", "title": "Installation, Exhibition Design, and Viewer Experience", "description": "Painting II includes the transition from studio object to public presentation. Students learn how exhibition choices shape meaning, attention, and professionalism.", "children": [{"id": "adb42069-ffea-4f19-a6a4-b2060ed7e774", "type": "subtopic", "title": "Exhibition planning", "children": [{"id": "2993822e-09d0-442e-87c5-c981afd0c560", "type": "concept", "title": "Wall layout"}, {"id": "673e979d-c014-4a9c-ab58-38ceda77b1b9", "type": "concept", "title": "Spacing and sightlines"}, {"id": "4bd148bc-78c1-4bc7-a6cf-2acd33425e3f", "type": "concept", "title": "Scale relationships"}], "description": "Students plan how works relate to one another in space."}, {"id": "90adfea9-bc61-48e1-9937-07ee3c4a6fba", "type": "subtopic", "title": "Finishing and display", "children": [{"id": "4a5b35c0-e992-4064-8385-2683cc501b99", "type": "concept", "title": "Edges and framing"}, {"id": "1d1b9304-f361-4ffd-95fb-4b0db9f1c638", "type": "concept", "title": "Hanging hardware"}, {"id": "88c65ba5-4ed5-4be9-9ae6-d037ced18f34", "type": "concept", "title": "Surface protection and transport"}], "description": "Finishing decisions affect how the painting is read and preserved."}, {"id": "fa946720-a11e-4056-81e9-18dd840e0f67", "type": "subtopic", "title": "Viewer experience", "children": [{"id": "7607fcb6-4229-4e41-bbd3-296efd607610", "type": "concept", "title": "First impression"}, {"id": "d0b4a0dc-eb68-4655-aee4-3afd8399a61c", "type": "concept", "title": "Viewing distance"}, {"id": "155d479d-7387-4b32-9987-2f5b81334558", "type": "concept", "title": "Rhythm across multiple works"}], "description": "Students consider how viewers enter, move through, and interpret the work."}]}, {"id": "0c8bfe84-811e-44e1-8051-3e612bc4c908", "type": "topic", "title": "Documentation, Portfolio, and Artist Statement", "description": "Advanced studio work needs accurate documentation and clear written support. Students learn to present their work for critique, transfer review, internships, exhibitions, and future study.", "children": [{"id": "cf1cdd09-d084-470b-afb4-b6b9ae0e2177", "type": "subtopic", "title": "Photographing paintings", "children": [{"id": "5383d2ca-d914-4ef2-bd76-0b838df5f8cf", "type": "concept", "title": "Lighting and glare control"}, {"id": "234b4b6d-8912-4357-83ae-04f458875a28", "type": "concept", "title": "Color correction"}, {"id": "6028965c-4ac9-4e93-bd03-967710bb39be", "type": "concept", "title": "File naming and metadata"}], "description": "Documentation must represent color, scale, edge, and surface honestly."}, {"id": "619eb91e-9ec1-4766-99f5-649a42b80265", "type": "subtopic", "title": "Portfolio construction", "children": [{"id": "801d4488-9234-4d42-9c1b-6f09833ef056", "type": "concept", "title": "Selection and sequence"}, {"id": "05bdbe5b-70ec-4392-a220-8b39e28b9d55", "type": "concept", "title": "Captions and dimensions"}, {"id": "70bd09b2-92a4-40b4-9516-2849529d8578", "type": "concept", "title": "Consistency of image quality"}], "description": "A portfolio is an argument about development and readiness."}, {"id": "ef6c324b-ee86-436f-8582-7dab07d96b36", "type": "subtopic", "title": "Artist statement writing", "children": [{"id": "4fb0b59f-7693-4284-8411-4c29c17a9ed8", "type": "concept", "title": "Plain-language claims"}, {"id": "6586fd53-54a3-4b37-b4e7-3d2f646f21f3", "type": "concept", "title": "Material and conceptual focus"}, {"id": "9c54a359-5640-4e63-925f-b43551486af7", "type": "concept", "title": "Revision after critique"}], "description": "The statement clarifies intentions, methods, and context without replacing the visual experience."}]}, {"id": "ad750893-eb4c-4c95-b72f-b8aaf183806a", "type": "topic", "title": "Professional Practice, Ethics, and Sustainability", "description": "Students learn habits that help sustain a painting practice beyond the course: ethical source use, safe material choices, exhibition readiness, and long-term organization.", "children": [{"id": "47ed7eb4-6443-4f9b-b8a5-3d3269c49ad5", "type": "subtopic", "title": "Professional materials and records", "children": [{"id": "e42a6b7c-db3d-48d2-b112-6c88eaa5e7de", "type": "concept", "title": "Inventory spreadsheets"}, {"id": "b232ff71-d097-4bf6-9c2e-2f592abc8e37", "type": "concept", "title": "Condition notes"}, {"id": "40560fda-30b5-4049-ad6c-21beb953dbe3", "type": "concept", "title": "Dimensions, media, and dates"}], "description": "Accurate records support exhibitions, applications, sales, and future archives."}, {"id": "3aa41854-f6d2-4c50-9fc5-ed2dff3ff4e8", "type": "subtopic", "title": "Ethics and rights", "children": [{"id": "845f174e-c7ce-4fc8-8295-da6357c20211", "type": "concept", "title": "Image rights"}, {"id": "fba0a063-690e-4290-b7f9-2781b1dee089", "type": "concept", "title": "Consent and representation"}, {"id": "bd2747bc-b2a3-4d1a-9406-f243c077aaba", "type": "concept", "title": "Cultural context and accountability"}], "description": "Advanced painting often works with images, bodies, cultures, and stories that require care."}, {"id": "832006c1-f8bb-45d6-a13f-16d3d535c1f1", "type": "subtopic", "title": "Sustainable studio systems", "children": [{"id": "d47fb67b-1c8f-4719-8010-8e92bb09a15c", "type": "concept", "title": "Low-toxicity processes"}, {"id": "7b7d040f-51d2-499e-a7d5-21a29eab69de", "type": "concept", "title": "Waste reduction"}, {"id": "25737230-2841-4138-b410-07f3283f7cdc", "type": "concept", "title": "Storage and reuse of materials"}], "description": "Sustainable practice protects health, budgets, and the environment."}]}, {"id": "04285aaa-a86a-46c5-9356-4454e403d62f", "type": "topic", "title": "Final Resolved Painting Series and Exhibition Review", "description": "The final unit asks students to complete a coherent body of painted work and present it with documentation, critical framing, and an exhibition-minded review.", "children": [{"id": "cc1e4047-d57b-4c2d-925f-6e60e148743d", "type": "subtopic", "title": "Final project proposal", "children": [{"id": "48f7e5d5-72ac-405f-b9cf-7c08f63988e0", "type": "concept", "title": "Concept and research statement"}, {"id": "e1abb95e-6d64-47d4-9a72-3c1a240d9a8f", "type": "concept", "title": "Precedent list"}, {"id": "68b7c35a-9137-4319-b6bd-a6b4d9583fb6", "type": "concept", "title": "Timeline and production plan"}], "description": "The proposal defines the series question, visual strategy, material plan, and evaluation criteria."}, {"id": "dfdc9b34-b0d9-47e7-80e6-32fe80ca40aa", "type": "subtopic", "title": "Resolved body of work", "children": [{"id": "e048a2f2-bc74-47a1-8869-b60cc7907ad6", "type": "concept", "title": "Three to five related works"}, {"id": "85c46a26-ee64-4642-9023-addd73d41bab", "type": "concept", "title": "Material and formal coherence"}, {"id": "b24d7da9-fb9c-4873-b193-48a916c0f44a", "type": "concept", "title": "Evidence of revision"}], "description": "Students complete connected paintings that demonstrate advanced technique and sustained inquiry."}, {"id": "ebfa03fd-f552-496a-8bbb-f20472fbc088", "type": "subtopic", "title": "Exhibition critique and reflection", "children": [{"id": "c1c42069-668c-4341-8a32-08dc2ae0dbc1", "type": "concept", "title": "Installation critique"}, {"id": "84ace66c-14bb-411e-b763-0866e4c09695", "type": "concept", "title": "Artist statement review"}, {"id": "05d8e83f-860f-4f7c-8f44-09657a7d0cc2", "type": "concept", "title": "Next-step development plan"}], "description": "The final review evaluates the work as a public-facing body rather than a single classroom assignment."}]}], "dbBacked": true}$pa2json$::jsonb,
