values
  ('05e01105-6f80-4535-9e1d-b8b4c833ce76', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Advanced Painting Practice and Ambitious Studio Goals', 'Painting II begins by moving students from assignment completion toward self-directed studio practice. The focus is on clearer intentions, stronger work habits, more ambitious problems, and the ability to sustain a project beyond a single exercise.', 0),
  ('70a2077d-cc71-49f6-93fb-0577a1899f02', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '05e01105-6f80-4535-9e1d-b8b4c833ce76', 'subtopic'::public.curated_course_node_type, 'Advanced studio expectations', 'Students learn what changes when painting becomes a sustained practice rather than a set of introductory studies.', 0),
  ('6d856d8a-a70a-4403-a6dc-07eec31279fc', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '70a2077d-cc71-49f6-93fb-0577a1899f02', 'concept'::public.curated_course_node_type, 'Independent project pacing', null, 0),
  ('5ee1cd72-0a66-4ba2-a692-8915ce9069a6', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '70a2077d-cc71-49f6-93fb-0577a1899f02', 'concept'::public.curated_course_node_type, 'Higher standards for revision', null, 1),
  ('d198d48d-89f7-4412-bb9a-3a16488123cc', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '70a2077d-cc71-49f6-93fb-0577a1899f02', 'concept'::public.curated_course_node_type, 'Risk-taking with technical follow-through', null, 2),
