  ('4997abf6-9cb2-461c-ae38-3df62f3ef23a', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'db08318b-32af-4174-befa-8b1109f69c39', 'concept'::public.curated_course_node_type, 'Studio proposal writing', null, 0),
