  ('71c5c4cd-fa6c-471e-a10b-ac740bcddcb6', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'db08318b-32af-4174-befa-8b1109f69c39', 'concept'::public.curated_course_node_type, 'Material and visual research logs', null, 2),
  ('acae2e87-dd5b-4b56-94ab-e6cb7d81e703', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '05e01105-6f80-4535-9e1d-b8b4c833ce76', 'subtopic'::public.curated_course_node_type, 'Reflective practice', 'Reflection helps students identify patterns in their choices and develop a more intentional practice.', 2),
  ('618d76ab-dbce-47cc-888a-e12b1ba2f18a', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'acae2e87-dd5b-4b56-94ab-e6cb7d81e703', 'concept'::public.curated_course_node_type, 'Process notes', null, 0),
  ('5d1b59bb-3dda-4b62-8636-7ceb7b8e4343', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'acae2e87-dd5b-4b56-94ab-e6cb7d81e703', 'concept'::public.curated_course_node_type, 'Failure analysis', null, 1),
  ('9947bcc2-65d8-431f-a5ea-4456345d8354', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'acae2e87-dd5b-4b56-94ab-e6cb7d81e703', 'concept'::public.curated_course_node_type, 'End-of-project self-assessment', null, 2),
  ('874658fe-cb44-4ccb-a735-ead647bdad5e', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Advanced Paint Handling, Surface, and Material Systems', 'This section deepens technical control of paint, support, ground, surface, and layering. Students learn to treat material decisions as expressive and conceptual choices, not merely craft preferences.', 1),
  ('9db27cb5-07ab-4448-9489-6ec4a28a6845', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '874658fe-cb44-4ccb-a735-ead647bdad5e', 'subtopic'::public.curated_course_node_type, 'Layering and surface complexity', 'Layering gives paintings depth, history, and a visible record of decisions.', 0),
  ('e5090524-2225-4636-a3fe-986d93d6335a', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '9db27cb5-07ab-4448-9489-6ec4a28a6845', 'concept'::public.curated_course_node_type, 'Glazing and scumbling', null, 0),
  ('be1add4f-fdcb-4150-bb1d-5242e6064c91', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '9db27cb5-07ab-4448-9489-6ec4a28a6845', 'concept'::public.curated_course_node_type, 'Scraping, sanding, and excavation', null, 1),
  ('51f5650e-85b5-4294-bc67-b3f73bd54bea', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '9db27cb5-07ab-4448-9489-6ec4a28a6845', 'concept'::public.curated_course_node_type, 'Transparency and opacity systems', null, 2),
  ('c05b5b0f-4c1b-43d5-8715-3800b3a6b21d', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '874658fe-cb44-4ccb-a735-ead647bdad5e', 'subtopic'::public.curated_course_node_type, 'Material behavior and compatibility', 'Students learn how different materials behave together so experimentation remains structurally sound.', 1),
  ('a3f40fae-88a4-49db-9c0f-ce47620896d0', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'c05b5b0f-4c1b-43d5-8715-3800b3a6b21d', 'concept'::public.curated_course_node_type, 'Acrylic over oil restrictions', null, 0),
  ('597cc55e-6388-4f5a-8900-28a468663bc0', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'c05b5b0f-4c1b-43d5-8715-3800b3a6b21d', 'concept'::public.curated_course_node_type, 'Mediums, binders, and grounds', null, 1),
  ('ec9eb698-d607-46e7-91a9-1242cfd0b810', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'c05b5b0f-4c1b-43d5-8715-3800b3a6b21d', 'concept'::public.curated_course_node_type, 'Archival risks and controlled exceptions', null, 2),
  ('284574a1-bda0-4ea2-a35a-c2fd29cb4778', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '874658fe-cb44-4ccb-a735-ead647bdad5e', 'subtopic'::public.curated_course_node_type, 'Surface as content', 'The surface can carry meaning through texture, damage, polish, accumulation, or restraint.', 2),
  ('d6c6812d-d58d-417a-98d3-09151f34b60b', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '284574a1-bda0-4ea2-a35a-c2fd29cb4778', 'concept'::public.curated_course_node_type, 'Smooth vs textured grounds', null, 0),
  ('9d1e3e2b-db1b-459c-a03a-881b00b32ca4', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '284574a1-bda0-4ea2-a35a-c2fd29cb4778', 'concept'::public.curated_course_node_type, 'Impasto and relief', null, 1),
  ('a099bfd0-74ea-43df-817a-ee1e4625f552', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '284574a1-bda0-4ea2-a35a-c2fd29cb4778', 'concept'::public.curated_course_node_type, 'Stain, seep, and exposed support', null, 2),
  ('35a7b382-f6ca-4089-a8a9-3fd3bfdc9e17', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Color, Light, and Perceptual Complexity', 'Painting II expects students to use color and light with greater subtlety. Color is studied as perception, structure, atmosphere, mood, and conceptual code.', 2),
  ('0921bd68-817e-4585-8d1e-1a5042143400', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '35a7b382-f6ca-4089-a8a9-3fd3bfdc9e17', 'subtopic'::public.curated_course_node_type, 'Advanced color relationships', 'Students refine color through relational judgment instead of formulaic color-wheel answers.', 0),
  ('3af56425-504d-477b-bb28-49b023e3b516', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '0921bd68-817e-4585-8d1e-1a5042143400', 'concept'::public.curated_course_node_type, 'Broken color', null, 0),
  ('2b20d571-e0b0-4fe2-9611-072f792aa683', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '0921bd68-817e-4585-8d1e-1a5042143400', 'concept'::public.curated_course_node_type, 'Simultaneous contrast', null, 1),
  ('127bcdef-05a9-4bf1-a97f-bb5f2164ae39', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '0921bd68-817e-4585-8d1e-1a5042143400', 'concept'::public.curated_course_node_type, 'Chroma control and color intervals', null, 2),
  ('d3e5d051-0ac3-4cdd-9af9-4c278785984d', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '35a7b382-f6ca-4089-a8a9-3fd3bfdc9e17', 'subtopic'::public.curated_course_node_type, 'Light as structure and mood', 'Light can organize space, establish time, and shape emotional tone.', 1),
  ('bd8fe6e5-fd0c-48fe-8c45-17dc5afb375b', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'd3e5d051-0ac3-4cdd-9af9-4c278785984d', 'concept'::public.curated_course_node_type, 'Artificial vs natural light', null, 0),
  ('dffcbf37-c945-4133-96cb-b53ba749f25a', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'd3e5d051-0ac3-4cdd-9af9-4c278785984d', 'concept'::public.curated_course_node_type, 'Atmospheric color', null, 1),
  ('61bf96e2-1a13-40af-8c57-75f0c1dd6a52', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'd3e5d051-0ac3-4cdd-9af9-4c278785984d', 'concept'::public.curated_course_node_type, 'Backlighting, glare, and reflected light', null, 2),
  ('a302972e-eaba-4fcf-b6d6-70dbb7bf95a1', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '35a7b382-f6ca-4089-a8a9-3fd3bfdc9e17', 'subtopic'::public.curated_course_node_type, 'Palette strategy', 'A coherent palette can unify a series and clarify a painter''s voice.', 2),
  ('3cb90035-449b-41fe-b886-ef8696f780c0', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a302972e-eaba-4fcf-b6d6-70dbb7bf95a1', 'concept'::public.curated_course_node_type, 'Restricted palettes', null, 0),
  ('59ad7277-0a9c-4dda-b8ad-b4fb8e73aca2', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a302972e-eaba-4fcf-b6d6-70dbb7bf95a1', 'concept'::public.curated_course_node_type, 'Key color and color anchors', null, 1),
  ('0656dd59-bfd0-4bb0-a4c1-6a972794761d', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a302972e-eaba-4fcf-b6d6-70dbb7bf95a1', 'concept'::public.curated_course_node_type, 'Palette shifts across a series', null, 2),
  ('77af2fb6-5de4-489c-bf69-d7cdb1703210', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Composition, Geometry, Scale, and Pictorial Architecture', 'Advanced composition asks students to build images with durable internal architecture. The painting should hold attention through structure, rhythm, balance, tension, and spatial intelligence.', 3);
