values
  ('b3ca4bd3-113b-4005-8297-e69ae0fdcc19', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '77af2fb6-5de4-489c-bf69-d7cdb1703210', 'subtopic'::public.curated_course_node_type, 'Compositional geometry', 'Geometry gives paintings an underlying order even when the surface looks intuitive.', 0),
