  ('d2facbc5-e48d-4de5-8f87-a07adad74ca2', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '77af2fb6-5de4-489c-bf69-d7cdb1703210', 'subtopic'::public.curated_course_node_type, 'Spatial compression and expansion', 'Students learn to move between illusionistic, shallow, fractured, and symbolic spaces.', 1),
