  ('3afcbdcf-2a97-41e7-aad9-ba7cee14734c', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'd2facbc5-e48d-4de5-8f87-a07adad74ca2', 'concept'::public.curated_course_node_type, 'Multiple viewpoints', null, 2),
  ('37a27e75-febd-476b-9665-cbdd7b8ae3d5', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '77af2fb6-5de4-489c-bf69-d7cdb1703210', 'subtopic'::public.curated_course_node_type, 'Compositional revision', 'Revision teaches students to improve a painting''s structure after the first idea has arrived.', 2),
  ('1142d3ae-0589-4d5d-8653-a63f62cfa601', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '37a27e75-febd-476b-9665-cbdd7b8ae3d5', 'concept'::public.curated_course_node_type, 'Cropping and reformatting', null, 0),
  ('aaac8e52-d5e8-4b9a-8cb7-5e46e5bed9e0', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '37a27e75-febd-476b-9665-cbdd7b8ae3d5', 'concept'::public.curated_course_node_type, 'Value redistribution', null, 1),
  ('d47e1ff3-d440-4e6b-bf76-d546cb88ea83', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '37a27e75-febd-476b-9665-cbdd7b8ae3d5', 'concept'::public.curated_course_node_type, 'Focal point control', null, 2),
  ('4f7b18ad-6258-4afb-b109-93475e367c18', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Large-Scale Painting and Physical Presence', 'Large-scale work changes the body, pace, tool choice, viewer distance, and installation logic of painting. Students learn how scale creates presence and responsibility.', 4),
  ('b3f8e6f9-feb4-4440-bfd2-af732380f9d9', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '4f7b18ad-6258-4afb-b109-93475e367c18', 'subtopic'::public.curated_course_node_type, 'Scaling up ideas', 'Not every small image survives enlargement, so students learn how to redesign for scale.', 0),
  ('c7e92f8e-927d-49a3-bc22-433bb4706994', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'b3f8e6f9-feb4-4440-bfd2-af732380f9d9', 'concept'::public.curated_course_node_type, 'Small study to large work', null, 0),
  ('9fe86db5-48cf-431b-a8c5-d9b70e3a2575', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'b3f8e6f9-feb4-4440-bfd2-af732380f9d9', 'concept'::public.curated_course_node_type, 'Mark size and viewing distance', null, 1),
  ('9c38fa51-5edc-4755-a10d-949cfc998e90', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'b3f8e6f9-feb4-4440-bfd2-af732380f9d9', 'concept'::public.curated_course_node_type, 'Format and support engineering', null, 2),
  ('ae845191-32f9-41ce-8805-9faee2d4bf9b', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '4f7b18ad-6258-4afb-b109-93475e367c18', 'subtopic'::public.curated_course_node_type, 'Physical painting methods', 'Large paintings require bodily movement, broader tools, and new sequencing.', 1),
  ('9d04cd14-e218-4292-b42c-6766b34395ef', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'ae845191-32f9-41ce-8805-9faee2d4bf9b', 'concept'::public.curated_course_node_type, 'Standing and wall-based work', null, 0),
  ('b3bdffd1-9b60-4e18-a5f2-631abc3275db', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'ae845191-32f9-41ce-8805-9faee2d4bf9b', 'concept'::public.curated_course_node_type, 'Large brushes, rollers, and pours', null, 1),
  ('e78171f9-186d-4ccb-b9dc-8e2d8a6e51c3', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'ae845191-32f9-41ce-8805-9faee2d4bf9b', 'concept'::public.curated_course_node_type, 'Working wet sections and drying time', null, 2),
  ('a29b77e4-0be6-429e-afce-a7947af808ed', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '4f7b18ad-6258-4afb-b109-93475e367c18', 'subtopic'::public.curated_course_node_type, 'Viewer encounter', 'Scale shapes whether a painting feels intimate, confrontational, immersive, or architectural.', 2),
  ('10648672-c298-40bb-95dd-a23db8077306', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a29b77e4-0be6-429e-afce-a7947af808ed', 'concept'::public.curated_course_node_type, 'Distance and approach', null, 0),
  ('90190283-359c-49fd-b56d-29ac903187b5', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a29b77e4-0be6-429e-afce-a7947af808ed', 'concept'::public.curated_course_node_type, 'Edge-to-edge activation', null, 1),
  ('cd7f1b9d-947d-4b9b-a7c9-0dab3f0085a2', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a29b77e4-0be6-429e-afce-a7947af808ed', 'concept'::public.curated_course_node_type, 'Installation height and sightline', null, 2),
  ('c750e67f-9aa9-41a4-978b-1a40a40b66a8', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Mixed Media, Collage, and Expanded Surface', 'Mixed media expands what a painting can contain and how it can be constructed. Students learn to integrate materials so additions feel necessary rather than decorative.', 5),
  ('dd9cbfea-8ea7-4fed-a86b-c2d177fb1111', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'c750e67f-9aa9-41a4-978b-1a40a40b66a8', 'subtopic'::public.curated_course_node_type, 'Collage and assemblage in painting', 'Collage introduces found material, fragmentation, and new relationships between image and object.', 0),
  ('e9d644bb-2a80-4fea-9ab3-314c654ae8ff', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'dd9cbfea-8ea7-4fed-a86b-c2d177fb1111', 'concept'::public.curated_course_node_type, 'Paper, fabric, photo, and print fragments', null, 0),
  ('b51b8c4d-48e3-4450-b537-01f28c327f14', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'dd9cbfea-8ea7-4fed-a86b-c2d177fb1111', 'concept'::public.curated_course_node_type, 'Adhesives and surface preparation', null, 1),
  ('496cbec3-d4ef-47f0-8f2e-bc0439ac9c8e', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'dd9cbfea-8ea7-4fed-a86b-c2d177fb1111', 'concept'::public.curated_course_node_type, 'Image interruption and layering', null, 2),
  ('d625bbd8-d8fd-4eeb-bebc-3d98ad429065', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'c750e67f-9aa9-41a4-978b-1a40a40b66a8', 'subtopic'::public.curated_course_node_type, 'Drawing, print, and digital transfer', 'Cross-media methods allow students to import marks, images, and systems into painting.', 1),
  ('2abdb783-ec9d-4db5-a2b2-b6c7c069ed80', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'd625bbd8-d8fd-4eeb-bebc-3d98ad429065', 'concept'::public.curated_course_node_type, 'Graphite, charcoal, ink, and pastel', null, 0),
  ('4cd1ca55-f167-48cd-a720-10f2fc3824ce', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'd625bbd8-d8fd-4eeb-bebc-3d98ad429065', 'concept'::public.curated_course_node_type, 'Monotype and transfer processes', null, 1),
  ('dce6085a-5a20-4540-b196-dca4821c5bb7', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'd625bbd8-d8fd-4eeb-bebc-3d98ad429065', 'concept'::public.curated_course_node_type, 'Digital sketches and printed sources', null, 2),
  ('a3e510e5-8e7a-473a-a1d2-cf9e9ff9b9f2', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'c750e67f-9aa9-41a4-978b-1a40a40b66a8', 'subtopic'::public.curated_course_node_type, 'Expanded painting', 'Painting can move beyond the stretched canvas into objects, walls, space, and installation.', 2),
  ('2c38661c-cf68-4eca-be23-ffc47cc0d90f', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a3e510e5-8e7a-473a-a1d2-cf9e9ff9b9f2', 'concept'::public.curated_course_node_type, 'Shaped supports', null, 0),
  ('750ab64e-765f-468a-92aa-2deedbe11fe5', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a3e510e5-8e7a-473a-a1d2-cf9e9ff9b9f2', 'concept'::public.curated_course_node_type, 'Painted objects', null, 1),
  ('c37ab2dd-c22e-43a8-b5c3-51f9b23c7380', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a3e510e5-8e7a-473a-a1d2-cf9e9ff9b9f2', 'concept'::public.curated_course_node_type, 'Modular panels and installation components', null, 2),
  ('06a28f19-2759-4073-9b74-7613efd60bfd', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Abstraction, Figuration, and Hybrid Image Languages', 'Painting II treats abstraction and figuration as a continuum. Students learn to decide how much recognition, ambiguity, gesture, and representation a painting needs.', 6),
  ('56060de0-5666-44e0-b35f-b7011541ebad', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '06a28f19-2759-4073-9b74-7613efd60bfd', 'subtopic'::public.curated_course_node_type, 'Advanced abstraction', 'Abstraction can be structured by process, sensation, systems, memory, or material logic.', 0);
