values
  ('c4779f8d-f739-4436-9d58-6748ee1b5f80', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '56060de0-5666-44e0-b35f-b7011541ebad', 'concept'::public.curated_course_node_type, 'Nonobjective composition', null, 0),
