  ('df7406db-ffd3-4b1c-91b5-26ac8a14fdc0', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '06a28f19-2759-4073-9b74-7613efd60bfd', 'subtopic'::public.curated_course_node_type, 'Figuration beyond likeness', 'Figuration can address body, identity, narrative, distortion, and psychological presence.', 1),
  ('1605b5ee-e6b3-469f-a9c3-1daca3e80240', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'df7406db-ffd3-4b1c-91b5-26ac8a14fdc0', 'concept'::public.curated_course_node_type, 'Distortion and simplification', null, 0),
  ('ad299d65-13c4-49e0-a16e-eee63d046b36', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'df7406db-ffd3-4b1c-91b5-26ac8a14fdc0', 'concept'::public.curated_course_node_type, 'Body fragments and silhouettes', null, 1),
  ('c7e4bbc4-75aa-4dca-80ef-64afa23b167e', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'df7406db-ffd3-4b1c-91b5-26ac8a14fdc0', 'concept'::public.curated_course_node_type, 'Symbolic or expressive figuration', null, 2),
  ('20bc8a2f-422b-455a-9a6d-c6b478e47e19', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '06a28f19-2759-4073-9b74-7613efd60bfd', 'subtopic'::public.curated_course_node_type, 'Hybrid languages', 'Hybrid painting allows recognition and abstraction to pressure each other.', 2),
  ('d03ab5b0-1222-413e-a553-caed5d1a774f', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '20bc8a2f-422b-455a-9a6d-c6b478e47e19', 'concept'::public.curated_course_node_type, 'Veiling and reveal', null, 0),
  ('62afa83f-b9df-41e1-ab03-cbf04b29089d', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '20bc8a2f-422b-455a-9a6d-c6b478e47e19', 'concept'::public.curated_course_node_type, 'Fragmented image fields', null, 1),
  ('a855d9cf-d917-42ba-9d33-eda2a5272e59', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '20bc8a2f-422b-455a-9a6d-c6b478e47e19', 'concept'::public.curated_course_node_type, 'Ambiguous figure-ground relationships', null, 2),
  ('b6d3bd05-dec6-4dff-a706-75d0537ddd22', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Painting from Imagination, Memory, and Invention', 'Students move beyond direct observation into invented imagery while preserving structural clarity and material conviction. Imagination becomes something built through sketches, references, memory, and revision.', 7),
  ('9a6f7a9f-98e5-4741-9f6f-accb0fd0068b', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'b6d3bd05-dec6-4dff-a706-75d0537ddd22', 'subtopic'::public.curated_course_node_type, 'Memory as source', 'Memory can transform observed experience into selective, emotionally charged imagery.', 0),
  ('937f7280-c5b5-439f-91f0-4edfe1bfebf5', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '9a6f7a9f-98e5-4741-9f6f-accb0fd0068b', 'concept'::public.curated_course_node_type, 'Memory mapping', null, 0),
  ('e81f2d9a-22f0-4dfb-a71a-ce24c7c1a820', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '9a6f7a9f-98e5-4741-9f6f-accb0fd0068b', 'concept'::public.curated_course_node_type, 'Reconstructed interiors and places', null, 1),
  ('7ffeccf6-94a7-4072-9ae3-c4b32bf9a07f', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '9a6f7a9f-98e5-4741-9f6f-accb0fd0068b', 'concept'::public.curated_course_node_type, 'Distortion through recollection', null, 2),
  ('c1c73f58-900d-4cf2-ba36-5d1074d92437', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'b6d3bd05-dec6-4dff-a706-75d0537ddd22', 'subtopic'::public.curated_course_node_type, 'Invented imagery', 'Invented paintings need internal logic even when they reject realism.', 1),
  ('db49c234-bf1c-4e5d-a59a-f94f0b6fa02a', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'c1c73f58-900d-4cf2-ba36-5d1074d92437', 'concept'::public.curated_course_node_type, 'World-building', null, 0),
  ('ed5ace82-9dca-40f8-8587-2513abf62347', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'c1c73f58-900d-4cf2-ba36-5d1074d92437', 'concept'::public.curated_course_node_type, 'Symbolic environments', null, 1),
  ('83fdaf9a-af44-4dea-a7a6-4cc661b778a0', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'c1c73f58-900d-4cf2-ba36-5d1074d92437', 'concept'::public.curated_course_node_type, 'Dream logic and surreal structures', null, 2),
  ('a905dc29-6d1c-4e4e-807b-7affcf62a8a7', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'b6d3bd05-dec6-4dff-a706-75d0537ddd22', 'subtopic'::public.curated_course_node_type, 'Reference synthesis', 'Advanced students combine references without letting any single source dominate.', 2),
  ('e7db94d1-6504-4f9a-a430-a8c7399e2be0', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a905dc29-6d1c-4e4e-807b-7affcf62a8a7', 'concept'::public.curated_course_node_type, 'Composite studies', null, 0),
  ('b5e2c33f-9163-4b4d-abb0-b02eb257f37d', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a905dc29-6d1c-4e4e-807b-7affcf62a8a7', 'concept'::public.curated_course_node_type, 'Reference hierarchy', null, 1),
  ('60de7b61-0c17-45c4-bfc4-d5f1bb88b25c', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a905dc29-6d1c-4e4e-807b-7affcf62a8a7', 'concept'::public.curated_course_node_type, 'Invented transitions and connective tissue', null, 2),
  ('d8ca1cd7-0540-45a9-9522-52096130c066', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Image Sources, Translation, Appropriation, and Screens', 'Contemporary painting often responds to photographs, online images, archives, film, and screens. Students learn to translate sources critically and ethically rather than simply reproduce them.', 8),
  ('718c14da-be1a-49a0-906c-fab0d6b5b851', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'd8ca1cd7-0540-45a9-9522-52096130c066', 'subtopic'::public.curated_course_node_type, 'Photo-based painting', 'Photo sources can support complex imagery, but translation must create painterly purpose.', 0),
  ('abf601f2-1987-42df-a38f-ad4fa6d71f59', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '718c14da-be1a-49a0-906c-fab0d6b5b851', 'concept'::public.curated_course_node_type, 'Cropping and framing', null, 0),
  ('f54e22ab-2f6d-4012-ad65-df0037d49046', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '718c14da-be1a-49a0-906c-fab0d6b5b851', 'concept'::public.curated_course_node_type, 'Lens distortion', null, 1),
  ('bfbb31ad-9ba3-4aab-abe1-3aa5fb2f54b3', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '718c14da-be1a-49a0-906c-fab0d6b5b851', 'concept'::public.curated_course_node_type, 'Color shifts from screen to paint', null, 2),
  ('4dbbd43c-538c-4c53-ab36-9170c3b2246e', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'd8ca1cd7-0540-45a9-9522-52096130c066', 'subtopic'::public.curated_course_node_type, 'Appropriation and citation', 'Borrowing images carries legal, ethical, and cultural responsibilities.', 1),
  ('cde779e0-b1f1-40a4-b1c2-0c9f253161e8', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '4dbbd43c-538c-4c53-ab36-9170c3b2246e', 'concept'::public.curated_course_node_type, 'Fair use basics', null, 0),
  ('bf3ed15b-6085-4b2f-bd88-41bda1ab754c', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '4dbbd43c-538c-4c53-ab36-9170c3b2246e', 'concept'::public.curated_course_node_type, 'Transformative use', null, 1),
  ('a0635df3-6db8-436a-9bd7-c1872019632d', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '4dbbd43c-538c-4c53-ab36-9170c3b2246e', 'concept'::public.curated_course_node_type, 'Source logs and attribution', null, 2),
  ('a260290d-dcb4-4b2d-b76f-db79c8812bb0', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'd8ca1cd7-0540-45a9-9522-52096130c066', 'subtopic'::public.curated_course_node_type, 'Painting after screens', 'Screens shape contemporary vision through glow, compression, repetition, and circulation.', 2),
  ('7e985090-8831-4d93-9426-57318c91c4bb', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a260290d-dcb4-4b2d-b76f-db79c8812bb0', 'concept'::public.curated_course_node_type, 'Pixelation and blur', null, 0),
  ('df8f1132-6265-406b-b54c-15a117af9dda', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a260290d-dcb4-4b2d-b76f-db79c8812bb0', 'concept'::public.curated_course_node_type, 'Scrolling and cropping', null, 1),
  ('d1dcf5df-a6ec-41ee-969e-754e7b2bf8fa', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a260290d-dcb4-4b2d-b76f-db79c8812bb0', 'concept'::public.curated_course_node_type, 'Digital artifacts as pictorial language', null, 2),
  ('505b203c-852a-42ee-b4df-3e62120b52af', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Conceptual Painting and Research Methods', 'Conceptual painting asks students to define the idea or question driving the work. Research becomes a studio tool for making paintings with stronger stakes and clearer intentions.', 9),
  ('225e7935-288a-4239-b21c-26d4bcc1f72c', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '505b203c-852a-42ee-b4df-3e62120b52af', 'subtopic'::public.curated_course_node_type, 'Concept development', 'Students learn to articulate what the painting investigates without overexplaining the image.', 0),
  ('7cf98d0b-acdc-4ce8-bbe5-bde2ef4a7ddc', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '225e7935-288a-4239-b21c-26d4bcc1f72c', 'concept'::public.curated_course_node_type, 'Project questions', null, 0);
