  ('a9f254b8-f644-45d4-a802-3833c05dc8be', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '505b203c-852a-42ee-b4df-3e62120b52af', 'subtopic'::public.curated_course_node_type, 'Form and concept alignment', 'The best conceptual choices are visible in the painting''s materials, scale, process, and presentation.', 2),
