  ('0fb9fb5e-abb0-4ccb-96dd-0ca806ca1e98', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'a9f254b8-f644-45d4-a802-3833c05dc8be', 'concept'::public.curated_course_node_type, 'Symbolic material choices', null, 1),
