  ('efb5cffe-e9e8-4fc6-9b71-4c903784452d', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Historical Influences, Artist Lineage, and Contemporary Context', 'Students build a conscious relationship to painting history and contemporary practice. The goal is to locate influences, not imitate them passively.', 10),
  ('308e6a67-c066-408f-935e-018f72cb04e9', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'efb5cffe-e9e8-4fc6-9b71-4c903784452d', 'subtopic'::public.curated_course_node_type, 'Historical reference as method', 'Historical study gives painters tools for composition, subject, surface, and argument.', 0),
  ('f228865c-002c-4cd4-96ad-ebb7d52b6b4d', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '308e6a67-c066-408f-935e-018f72cb04e9', 'concept'::public.curated_course_node_type, 'Modernism and abstraction', null, 0),
  ('54eed714-34a1-49a7-a2c5-10e2cf505940', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '308e6a67-c066-408f-935e-018f72cb04e9', 'concept'::public.curated_course_node_type, 'Expressionism and realism', null, 1),
  ('75364731-dcda-4dd9-99dd-2b7daa91f81d', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '308e6a67-c066-408f-935e-018f72cb04e9', 'concept'::public.curated_course_node_type, 'Still life, landscape, portrait traditions', null, 2),
  ('bffaf9e2-9d6b-4851-97ec-01b8de42e23d', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'efb5cffe-e9e8-4fc6-9b71-4c903784452d', 'subtopic'::public.curated_course_node_type, 'Contemporary painting debates', 'Students examine current questions about medium, image culture, identity, and global art contexts.', 1),
  ('e18671d4-74b4-445a-b327-a36cd56cbff2', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'bffaf9e2-9d6b-4851-97ec-01b8de42e23d', 'concept'::public.curated_course_node_type, 'Painting after photography', null, 0),
  ('1714d659-500b-4d49-912e-bd967236c6a4', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'bffaf9e2-9d6b-4851-97ec-01b8de42e23d', 'concept'::public.curated_course_node_type, 'Expanded painting', null, 1),
  ('3628a8f2-709f-4fbc-8b62-163ed23722ab', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'bffaf9e2-9d6b-4851-97ec-01b8de42e23d', 'concept'::public.curated_course_node_type, 'Global and decolonial perspectives', null, 2),
  ('7ae1a66f-b7bf-4ce7-92bb-8bee63af2b06', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'efb5cffe-e9e8-4fc6-9b71-4c903784452d', 'subtopic'::public.curated_course_node_type, 'Artist lineage mapping', 'Lineage maps help students identify where their work sits in relation to others.', 2),
  ('6257d370-f55b-42c2-9231-64c789254582', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '7ae1a66f-b7bf-4ce7-92bb-8bee63af2b06', 'concept'::public.curated_course_node_type, 'Influence charts', null, 0),
  ('33ce2e6e-7d22-4cbf-a259-7903736dc8a0', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '7ae1a66f-b7bf-4ce7-92bb-8bee63af2b06', 'concept'::public.curated_course_node_type, 'Formal comparison', null, 1),
  ('b51b210d-3475-4eec-824f-1c5e2529e873', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '7ae1a66f-b7bf-4ce7-92bb-8bee63af2b06', 'concept'::public.curated_course_node_type, 'Critical distance from influences', null, 2),
  ('835fcc05-766c-4780-99f0-8e56e5d4c296', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Series Development and Body of Work', 'Painting II should culminate in connected work, not isolated assignments. Series development teaches continuity, variation, pacing, and depth.', 11),
