  ('fea43eb9-2715-4840-aab1-8ccaad6cb51d', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'f7bf1f18-889b-4f60-b1ee-6689f1e755c6', 'concept'::public.curated_course_node_type, 'Theme and motif', null, 0),
  ('971a8d2c-ce19-4281-9c90-066056759532', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'f7bf1f18-889b-4f60-b1ee-6689f1e755c6', 'concept'::public.curated_course_node_type, 'Rule-based variation', null, 1),
  ('82b04d20-5951-4afe-bc10-2a112c3c7ada', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'f7bf1f18-889b-4f60-b1ee-6689f1e755c6', 'concept'::public.curated_course_node_type, 'Formal continuity', null, 2),
  ('5765b29a-8933-4475-95dc-62deebb7f298', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '835fcc05-766c-4780-99f0-8e56e5d4c296', 'subtopic'::public.curated_course_node_type, 'Editing and sequencing', 'Editing teaches students what belongs, what repeats too easily, and what strengthens the whole.', 1),
  ('43c33e89-020f-4de5-9bb9-e293988eca10', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '5765b29a-8933-4475-95dc-62deebb7f298', 'concept'::public.curated_course_node_type, 'Selecting strongest works', null, 0),
  ('24c73416-dacd-4412-8fb1-cac7ab2df42a', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '5765b29a-8933-4475-95dc-62deebb7f298', 'concept'::public.curated_course_node_type, 'Pacing contrast', null, 1),
  ('8b214814-8fbd-488a-8c42-ea1615a9f8c4', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '5765b29a-8933-4475-95dc-62deebb7f298', 'concept'::public.curated_course_node_type, 'Sequence as meaning', null, 2),
  ('c701c62d-83b8-4231-b275-20ae276c561c', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '835fcc05-766c-4780-99f0-8e56e5d4c296', 'subtopic'::public.curated_course_node_type, 'Development over time', 'A body of work should show evolution rather than repetition.', 2),
  ('68da55af-50f7-427e-b41f-138884feecd8', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'c701c62d-83b8-4231-b275-20ae276c561c', 'concept'::public.curated_course_node_type, 'Versioning', null, 0),
  ('2a456beb-ec1a-497a-b1dd-f96c6311ff31', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'c701c62d-83b8-4231-b275-20ae276c561c', 'concept'::public.curated_course_node_type, 'Breakthrough and dead-end analysis', null, 1),
  ('49575fde-b1df-48e1-951e-7c3a8425f59c', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'c701c62d-83b8-4231-b275-20ae276c561c', 'concept'::public.curated_course_node_type, 'Progressive complexity', null, 2),
  ('4ada26e2-768b-4665-87ad-b20e8ee5e3a6', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', null, 'topic'::public.curated_course_node_type, 'Personal Voice, Style, and Critical Position', 'Personal voice is treated as an emerging pattern of commitments, questions, materials, and visual decisions. Style is not decoration; it is the visible structure of a painter''s thinking.', 12),
  ('38deb6e9-1278-4b61-abee-01f1394b73c5', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '4ada26e2-768b-4665-87ad-b20e8ee5e3a6', 'subtopic'::public.curated_course_node_type, 'Identifying recurring concerns', 'Students learn to recognize what they return to and why it matters.', 0),
  ('580e418a-1a2b-4ba2-ad91-a81c8079a7fe', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '38deb6e9-1278-4b61-abee-01f1394b73c5', 'concept'::public.curated_course_node_type, 'Motifs and subjects', null, 0),
  ('2bb08649-bba2-4038-b86b-8d8fd5217f72', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '38deb6e9-1278-4b61-abee-01f1394b73c5', 'concept'::public.curated_course_node_type, 'Material preferences', null, 1);
