  ('bff31d93-bd99-4c5e-b338-164ddfb0c3c1', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '3ca7d589-2f7d-4874-a0b4-dbe9478a8dd4', 'concept'::public.curated_course_node_type, 'Social and personal stakes', null, 1),
