  ('92c48739-3b1b-429d-8f8a-fdbc388574bf', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '26927f61-5aab-4c0c-ba84-8347a3e5870a', 'subtopic'::public.curated_course_node_type, 'Advanced critique formats', 'Different critique structures reveal different kinds of information about a painting.', 0),
  ('0c96dcc6-147f-42ff-bc98-90bae2d670c1', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', '92c48739-3b1b-429d-8f8a-fdbc388574bf', 'concept'::public.curated_course_node_type, 'Formal critique', null, 0),
