  ('acc23e6b-e793-4475-98fc-caf30873f388', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'eb838a1f-33b0-434f-8ce3-7cdf2a676eda', 'concept'::public.curated_course_node_type, 'Overpainting', null, 0),
  ('f79bb9c4-c45c-4785-82c2-80b9a4b324a8', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'eb838a1f-33b0-434f-8ce3-7cdf2a676eda', 'concept'::public.curated_course_node_type, 'Structural change', null, 1),
  ('d63f7e1e-e3ad-47b4-aa1a-bfacb55ebabd', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'eb838a1f-33b0-434f-8ce3-7cdf2a676eda', 'concept'::public.curated_course_node_type, 'Documenting before/after decisions', null, 2),
