  ('155d479d-7387-4b32-9987-2f5b81334558', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'fa946720-a11e-4056-81e9-18dd840e0f67', 'concept'::public.curated_course_node_type, 'Rhythm across multiple works', null, 2),
