  ('5383d2ca-d914-4ef2-bd76-0b838df5f8cf', 'c9d0e1f2-3a4b-4c61-8f01-1a2b3c4d5e71', 'cf1cdd09-d084-470b-afb4-b6b9ae0e2177', 'concept'::public.curated_course_node_type, 'Lighting and glare control', null, 0),
